import{_ as e,o as i,c as a,a2 as s}from"./chunks/framework.BI_TNnOW.js";const k=JSON.parse('{"title":"Conditions evaluation","description":"","frontmatter":{},"headers":[],"relativePath":"en/content/100-conditions-evaluation.md","filePath":"en/content/100-conditions-evaluation.md"}'),d={name:"en/content/100-conditions-evaluation.md"};function o(n,t,h,l,c,r){return i(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="conditions-evaluation" tabindex="-1">Conditions evaluation <a class="header-anchor" href="#conditions-evaluation" aria-label="Permalink to &quot;Conditions evaluation&quot;">​</a></h1><p>In Bash, conditions are evaluated using the <code>test</code> command or the equivalent <code>[ ]</code> form. These tools allow you to verify conditions and control the execution flow in scripts.</p><h2 id="using" tabindex="-1">Using <code>$?</code> <a class="header-anchor" href="#using" aria-label="Permalink to &quot;Using `$?`&quot;">​</a></h2><p>The <code>$?</code> symbol is used in Bash to get the exit code of the last executed command. This exit code is:</p><ul><li><code>0</code> if the command executed successfully or the condition is true.</li><li><code>1</code> (or any other non-zero value) if the command failed or the condition is false.</li></ul><h2 id="using-test-and" tabindex="-1">Using <code>test</code> and <code>[]</code> <a class="header-anchor" href="#using-test-and" aria-label="Permalink to &quot;Using `test` and `[]`&quot;">​</a></h2><p>The following code executed directly in the terminal checks if <code>10</code> is greater than <code>20</code> using <code>test</code>. Since the condition is false, the exit code will be <code>1</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -gt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $?</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Expected output: 1</span></span></code></pre></div><p>The following code executed directly in the terminal evaluates if <code>10</code> is greater than <code>20</code> using <code>[ ]</code>. Since the condition is false, it will also return <code>1</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -gt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $?</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Expected output: 1</span></span></code></pre></div><p>This example uses <code>test</code> together with the <code>&amp;&amp;</code> and <code>||</code> operators to print &quot;True&quot; if the condition is true, or &quot;False&quot; if it is false:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -gt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> True</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> False</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Expected output: False</span></span></code></pre></div><p>Here, <code>[ ]</code> is used with the same operators to check if <code>10</code> is less than <code>20</code> and return the corresponding message:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -lt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ] &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> True</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> False</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Expected output: True</span></span></code></pre></div><h2 id="common-operators-and-evaluations" tabindex="-1">Common operators and evaluations <a class="header-anchor" href="#common-operators-and-evaluations" aria-label="Permalink to &quot;Common operators and evaluations&quot;">​</a></h2><h3 id="number-comparison" tabindex="-1">Number comparison <a class="header-anchor" href="#number-comparison" aria-label="Permalink to &quot;Number comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>-eq</code></td><td>Equal to</td><td><code>[ 5 -eq 5 ]</code></td></tr><tr><td><code>-ne</code></td><td>Not equal to</td><td><code>[ 5 -ne 3 ]</code></td></tr><tr><td><code>-gt</code></td><td>Greater than</td><td><code>[ 5 -gt 3 ]</code></td></tr><tr><td><code>-lt</code></td><td>Less than</td><td><code>[ 3 -lt 5 ]</code></td></tr><tr><td><code>-ge</code></td><td>Greater than or equal to</td><td><code>[ 5 -ge 5 ]</code></td></tr><tr><td><code>-le</code></td><td>Less than or equal to</td><td><code>[ 3 -le 5 ]</code></td></tr></tbody></table><h3 id="string-comparison" tabindex="-1">String comparison <a class="header-anchor" href="#string-comparison" aria-label="Permalink to &quot;String comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>=</code></td><td>Equal to</td><td><code>[ &quot;a&quot; = &quot;a&quot; ]</code></td></tr><tr><td><code>!=</code></td><td>Not equal to</td><td><code>[ &quot;a&quot; != &quot;b&quot; ]</code></td></tr><tr><td><code>-z</code></td><td>Empty string</td><td><code>[ -z &quot;&quot; ]</code></td></tr><tr><td><code>-n</code></td><td>Non-empty string</td><td><code>[ -n &quot;hello&quot; ]</code></td></tr></tbody></table><h3 id="file-evaluation" tabindex="-1">File evaluation <a class="header-anchor" href="#file-evaluation" aria-label="Permalink to &quot;File evaluation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>-e</code></td><td>Exists</td><td><code>[ -e file ]</code></td></tr><tr><td><code>-f</code></td><td>Is a regular file</td><td><code>[ -f file ]</code></td></tr><tr><td><code>-d</code></td><td>Is a directory</td><td><code>[ -d directory ]</code></td></tr><tr><td><code>-r</code></td><td>Has read permissions</td><td><code>[ -r file ]</code></td></tr><tr><td><code>-w</code></td><td>Has write permissions</td><td><code>[ -w file ]</code></td></tr><tr><td><code>-x</code></td><td>Has execute permissions</td><td><code>[ -x file ]</code></td></tr></tbody></table>',21)])])}const u=e(d,[["render",o]]);export{k as __pageData,u as default};
